CREATE TABLE IF NOT EXISTS parties (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, code text NOT NULL, kind text NOT NULL CHECK (kind IN ('customer','supplier','both')), name text NOT NULL, legal_name text, tax_no text, national_id text, address jsonb, phone text, email text, receivable_account_id uuid REFERENCES accounts(id) ON DELETE RESTRICT, payable_account_id uuid REFERENCES accounts(id) ON DELETE RESTRICT, credit_limit numeric(20,4) NOT NULL DEFAULT 0 CHECK (credit_limit >= 0), is_owner boolean NOT NULL DEFAULT false, is_contractor boolean NOT NULL DEFAULT false, branch_id uuid REFERENCES branches(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid);
CREATE UNIQUE INDEX IF NOT EXISTS parties_tenant_code_key ON parties(tenant_id, code) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS parties_tenant_tax_idx ON parties(tenant_id, tax_no);
CREATE INDEX IF NOT EXISTS parties_tenant_kind_idx ON parties(tenant_id, kind);
CREATE TABLE IF NOT EXISTS party_contacts (party_id uuid NOT NULL REFERENCES parties(id) ON DELETE CASCADE, id uuid NOT NULL, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, name text NOT NULL, role text, phone text, email text, is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, PRIMARY KEY (party_id, id));
CREATE INDEX IF NOT EXISTS party_contacts_tenant_party_idx ON party_contacts(tenant_id, party_id);
CREATE TABLE IF NOT EXISTS payment_allocations (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, party_id uuid NOT NULL REFERENCES parties(id) ON DELETE RESTRICT, voucher_id uuid, invoice_kind text NOT NULL, invoice_id uuid NOT NULL, amount numeric(20,4) NOT NULL CHECK (amount > 0), allocated_at timestamptz NOT NULL DEFAULT now(), created_by uuid);
CREATE INDEX IF NOT EXISTS payment_allocations_invoice_idx ON payment_allocations(tenant_id, invoice_kind, invoice_id);
CREATE INDEX IF NOT EXISTS payment_allocations_party_idx ON payment_allocations(tenant_id, party_id);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['parties','party_contacts','payment_allocations'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t); EXECUTE format('DROP POLICY IF EXISTS %I_tenant_isolation ON %I', t, t); EXECUTE format('CREATE POLICY %I_tenant_isolation ON %I USING (tenant_id = current_setting(''app.tenant_id'', true)::uuid) WITH CHECK (tenant_id = current_setting(''app.tenant_id'', true)::uuid)', t, t); END LOOP; END $$;
